#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Salam, Arduino!");
}

void loop() {
  const int value = analogRead(A0);
  lcd.setCursor(0, 1);
  lcd.print("Sensor: ");
  lcd.print(value);
  lcd.print("    ");
  delay(250);
}
